(function(root){'use strict';const key='science-studio-missions-v1',delay=24*60*60*1000;
function clean(raw,bank){const out={version:1,records:{}};if(raw?.version!==1)return out;for(const m of bank){const r=raw.records?.[m.id];if(!r||r.version!==m.version)continue;const x={version:m.version,reflection:typeof r.reflection==='string'?r.reflection.slice(0,1500):'',initial:null,recheck:null,practiceAt:0};for(const [stage,i] of [['initial',0],['recheck',1]]){const a=r[stage];if(a&&Number.isInteger(a.answer)&&a.answer>=0&&a.answer<m.questions[i].options.length&&Number.isFinite(a.at)&&a.at>0)x[stage]={answer:a.answer,at:a.at};}if(x.initial?.answer===m.questions[0].correct&&Number.isFinite(r.practiceAt)&&r.practiceAt>0&&r.practiceAt<=x.initial.at&&x.reflection.trim().length>=20)x.practiceAt=r.practiceAt;if(!x.practiceAt||x.recheck?.at<x.practiceAt+delay)x.recheck=null;out.records[m.id]=x;}return out;}
function status(m,r,ready,now){if(r?.practiceAt&&r.recheck?.answer===m.questions[1].correct)return 'demonstrated';if(r?.practiceAt)return now>=r.practiceAt+delay?'recheck':'waiting';return ready?'challenge':r?.reflection?.trim()?'practising':'ready';}
function answer(raw,bank,id,stage,value,ready,now){const out=clean(raw,bank),m=bank.find(m=>m.id===id);if(!m||!['initial','recheck'].includes(stage)||!Number.isInteger(value)||value<0||value>=m.questions[stage==='initial'?0:1].options.length||!Number.isFinite(now)||now<=0)return out;const r=out.records[id]||{version:m.version,reflection:'',practiceAt:0,initial:null,recheck:null};if(status(m,r,ready,now)==='demonstrated')return out;if(stage==='initial'){if(!ready||r.reflection.trim().length<20||r.practiceAt)return out;r.initial={answer:value,at:now};if(value===m.questions[0].correct)r.practiceAt=now;}else{if(!r.practiceAt||now<r.practiceAt+delay)return out;r.recheck={answer:value,at:now};}out.records[id]=r;return out;}
function recommend(bank,records,gaps,failedVideos,now){const ranked=bank.map(m=>{const r=records[m.id],s=status(m,r,false,now),gap=gaps.includes(m.objective),video=failedVideos.includes(m.video);return{...m,reason:gap?'Missed objective in your latest marked mock':video?'Your latest linked video check needs revision':s==='recheck'?'Your follow-up challenge is ready':r?'Continue your saved mission':'Build a core skill',score:s==='demonstrated'?-100:s==='waiting'?-1:s==='recheck'?100:gap?80:video?70:r?60:m.extension?-10:10};}).filter(m=>m.score>=0).sort((a,b)=>b.score-a.score);const picks=[],topics=new Set();while(picks.length<3&&ranked.length){ranked.sort((a,b)=>(b.score-(topics.has(b.topic)?15:0))-(a.score-(topics.has(a.topic)?15:0)));const next=ranked.shift();picks.push(next);topics.add(next.topic);}return picks;}
const api={key,delay,clean,status,answer,recommend};if(typeof module!=='undefined')module.exports=api;else root.MissionCore=api;})(globalThis);
